let stack = [10, 20, 30];

stack.push(40);          // [10, 20, 30, 40]
console.log(stack);

let removed = stack.pop(); // removes 40
console.log(removed);     // 40
console.log(stack);       // [10, 20, 30]

let queue = ["a", "b", "c"];

queue.unshift("z");       // ["z", "a", "b", "c"]
console.log(queue);

let first = queue.shift(); // removes "z"
console.log(first);        // "z"
console.log(queue);        // ["a", "b", "c"]

let colors = ["red", "green", "blue", "yellow"];

let middle = colors.slice(1, 3);
console.log(middle);   // ["green", "blue"]
console.log(colors);   // ["red", "green", "blue", "yellow"] — unchanged!

let fromIndex2 = colors.slice(2);
console.log(fromIndex2); // ["blue", "yellow"]

let items = ["a", "b", "c", "d"];

// Remove 2 elements starting at index 1
let removed = items.splice(1, 2);
console.log(removed);  // ["b", "c"]
console.log(items);    // ["a", "d"]

// Insert at index 1 (remove 0)
items.splice(1, 0, "x", "y");
console.log(items);    // ["a", "x", "y", "d"]

let rgb = [255, 128, 0];

let [red, green, blue] = rgb;

console.log(red);    // 255
console.log(green);  // 128
console.log(blue);   // 0

// Skip elements with commas
let [r, , b] = rgb;
console.log(r);  // 255
console.log(b);  // 0

let arr1 = [1, 2, 3];
let arr2 = [4, 5, 6];

// Copy an array
let copy = [...arr1];
console.log(copy);  // [1, 2, 3]

// Merge arrays
let merged = [...arr1, ...arr2];
console.log(merged);  // [1, 2, 3, 4, 5, 6]

// Add elements while copying
let extended = [...arr1, 99, ...arr2];
console.log(extended);  // [1, 2, 3, 99, 4, 5, 6]
